opening = 820_000_000
ins = {"매출채권 회수": 55_000_000, "대출 인출": 300_000_000}
outs = {"거래처 지급": 41_800_000, "CAPEX(서버 선급금)": 250_000_000, "이자": 4_000_000}
closing = opening + sum(ins.values()) - sum(outs.values())
bank = {"주거래 보통예금": 600_000_000, "MMDA": 279_200_000}
print(f"장부 {closing:,} / 은행 {sum(bank.values()):,} / 차이 {sum(bank.values()) - closing:,}")
# 장부 879,200,000 / 은행 879,200,000 / 차이 0
